class Solution {
  public int maxScore(int[] nums, int maxVal) {
    int MAX = 100_001;
    int n = nums.length;
    int[] freq = new int[MAX], multiples = new int[MAX], mu = new int[MAX];
    for (int v : nums) freq[v]++;
    for (int d = 1; d < MAX; d++) for (int m = d; m < MAX; m += d) multiples[d] += freq[m];
    mu[1] = 1;
    boolean[] composite = new boolean[MAX];
    List<Integer> primes = new ArrayList<>();
    for (int i = 2; i < MAX; i++) {
      if (!composite[i]) {
        primes.add(i);
        mu[i] = -1;
      }
      for (int p : primes) {
        if ((long) i * p >= MAX) break;
        composite[i * p] = true;
        if (i % p == 0) {
          mu[i * p] = 0;
          break;
        }
        mu[i * p] = -mu[i];
      }
    }
    int[] coprime = new int[MAX];
    for (int d = 1; d < MAX; d++) {
      if (mu[d] == 0) continue;
      for (int m = d; m < MAX; m += d) coprime[m] += mu[d] * multiples[d];
    }
    long best = Long.MIN_VALUE;
    for (int v = 1; v < MAX; v++) {
      int cnt = n - coprime[v];
      if (v <= maxVal) best = Math.max(best, (long) v - (cnt > 0 ? cnt : 1));
      if (freq[v] > 0) best = Math.max(best, (long) v - (cnt - (v > 1 ? 1 : 0)));
    }
    return (int) best;
  }
}
